// Command gen regenerates the English error catalog the external API answers with,
// from the panel's own English dictionary.
//
// The texts are NOT re-authored here: web/src/i18n/en.ts already holds an English
// string for every err.* code (TestErrorCodesHaveDictionaryEntries makes sure of it),
// and a second hand-written copy would be a second thing to forget. This lifts that
// one into Go so a server with no checkout beside it can still answer in English.
//
// Run with `go generate ./internal/i18n/...`; TestErrorCatalogIsCurrent fails when
// the generated file and the dictionary have drifted apart.
package main

import (
	"bytes"
	"fmt"
	"go/format"
	"os"
	"sort"
	"strconv"

	"github.com/AppsGanin/rospanel/internal/i18n/dictcheck"
)

func main() {
	entries, err := dictcheck.ErrorsEN(".")
	if err != nil {
		fmt.Fprintln(os.Stderr, "read dictionary:", err)
		os.Exit(1)
	}
	if len(entries) == 0 {
		fmt.Fprintln(os.Stderr, "no err.* entries found — did the dictionary shape change?")
		os.Exit(1)
	}

	keys := make([]string, 0, len(entries))
	for k := range entries {
		keys = append(keys, k)
	}
	sort.Strings(keys)

	var b bytes.Buffer
	b.WriteString("// Code generated by internal/i18n/gen. DO NOT EDIT.\n")
	b.WriteString("// Source: web/src/i18n/en.ts (the `err` section).\n\n")
	b.WriteString("package i18n\n\n")
	b.WriteString("// errEN is the English text of every error code the panel can raise, keyed by the\n")
	b.WriteString("// same code the panel UI translates. The external API renders these; the panel\n")
	b.WriteString("// keeps translating in the browser, in whichever language the admin picked.\n")
	b.WriteString("var errEN = map[string]string{\n")
	for _, k := range keys {
		fmt.Fprintf(&b, "\t%s: %s,\n", strconv.Quote(k), strconv.Quote(entries[k]))
	}
	b.WriteString("}\n")

	src, err := format.Source(b.Bytes())
	if err != nil {
		fmt.Fprintln(os.Stderr, "gofmt:", err)
		os.Exit(1)
	}
	if err := os.WriteFile("errcatalog_gen.go", src, 0o644); err != nil {
		fmt.Fprintln(os.Stderr, "write:", err)
		os.Exit(1)
	}
	fmt.Printf("errcatalog_gen.go: %d codes\n", len(keys))
}
